  "collapsible-overlay": "'use client';\n\nimport React from 'react';\nimport {\n  DesktopOutlined,\n  FileOutlined,\n  MenuFoldOutlined,\n  MenuUnfoldOutlined,\n  PieChartOutlined,\n  TeamOutlined,\n} from '@ant-design/icons';\nimport type { MenuProps } from '@ceebee/ui/client';\nimport { Layout, Menu, theme } from '@ceebee/ui/client';\n\nconst { Header, Content, Footer, Sider } = Layout;\n\nconst layoutStyle: React.CSSProperties = {\n  position: 'relative',\n  minHeight: 360,\n};\n\nconst siderStyle: React.CSSProperties = {\n  position: 'absolute',\n  top: 0,\n  bottom: 0,\n  insetInlineStart: 0,\n  zIndex: 10,\n};\n\nconst items: MenuProps['items'] = [\n  PieChartOutlined,\n  DesktopOutlined,\n  TeamOutlined,\n  FileOutlined,\n].map((icon, index) => ({\n  key: String(index + 1),\n  icon: React.createElement(icon),\n  label: `nav ${index + 1}`,\n}));\n\nconst App: React.FC = () => {\n  const [collapsed, setCollapsed] = React.useState(false);\n  const {\n    token: { colorBgContainer, borderRadiusLG },\n  } = theme.useToken();\n\n  const currentYear = new Date().getFullYear();\n\n  return (\n    <Layout style={layoutStyle}>\n      <Sider\n        collapsible\n        collapsed={collapsed}\n        collapsedWidth=\"0\"\n        style={siderStyle}\n        trigger={collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}\n        onCollapse={setCollapsed}\n      >\n        <div className=\"demo-logo-vertical\" />\n        <Menu theme=\"dark\" mode=\"inline\" defaultSelectedKeys={['1']} items={items} />\n      </Sider>\n      <Layout>\n        <Header\n          style={{\n            padding: 0,\n            background: colorBgContainer,\n          }}\n        />\n        <Content style={{ margin: '24px 16px 0' }}>\n          <div\n            style={{\n              padding: 24,\n              minHeight: 240,\n              background: colorBgContainer,\n              borderRadius: borderRadiusLG,\n            }}\n          >\n            Content keeps its full width when the sider overlays it.\n          </div>\n        </Content>\n        <Footer style={{ textAlign: 'center' }}>\n          Ceebee UI ©{currentYear} Created by Ceebee\n        </Footer>\n      </Layout>\n    </Layout>\n  );\n};\n\nexport default App;\n\n",
